sys_ws_operation.operation_script:
(function process(request, response) {

    try {

        var managerId =
            gs.getUserID();


        // =====================================================
        // INDIA DATE
        // =====================================================
        var now =
            new GlideDateTime();

        var indiaNow =
            new GlideDateTime(now);

        indiaNow.addSeconds(19800);

        var indiaValue =
            indiaNow.getValue();

        var today =
            indiaValue.substring(0, 10);


        // Last 7 days including today
        var startDateTime =
            new GlideDateTime(indiaNow);

        startDateTime.addDaysUTC(-6);

        var startDate =
            startDateTime
                .getValue()
                .substring(0, 10);


        // =====================================================
        // GET EMPLOYEES UNDER CURRENT MANAGER
        // =====================================================
        var profile =
            new GlideRecord(
                'x_1760545_smarta_0_employee_profile'
            );

        profile.addQuery(
            'manager',
            managerId
        );

        profile.addQuery(
            'active',
            true
        );

        profile.orderBy(
            'employee'
        );

        profile.query();


        var employeeIds = [];
        var employeeInfo = {};


        while (profile.next()) {

            var employeeId =
                profile.getValue(
                    'employee'
                );


            employeeIds.push(
                employeeId
            );


            employeeInfo[
                employeeId
            ] = {

                employee_id:
                    employeeId,

                employee:
                    profile.employee
                        .getDisplayValue(),

                employee_code:
                    profile.getValue(
                        'employee_code'
                    ) || '',

                department:
                    profile.getValue(
                        'department'
                    ) || '',

                shift:
                    profile.shift
                        .getDisplayValue() || ''

            };

        }


        // =====================================================
        // TODAY SUMMARY
        // =====================================================
        var todaySummary = {

            total_employees:
                employeeIds.length,

            checked_in:
                0,

            checked_out:
                0,

            not_checked_in:
                employeeIds.length,

            late:
                0,

            present:
                0,

            half_day:
                0,

            insufficient_hours:
                0

        };


        var todayRows = [];


        for (
            var i = 0;
            i < employeeIds.length;
            i++
        ) {

            var empId =
                employeeIds[i];


            var info =
                employeeInfo[
                    empId
                ];


            var attendance =
                new GlideRecord(
                    'x_1760545_smarta_0_attendance'
                );

            attendance.addQuery(
                'employee',
                empId
            );

            attendance.addQuery(
                'attendance_date',
                today
            );

            attendance.setLimit(1);

            attendance.query();


            var row = {

                employee_id:
                    empId,

                employee:
                    info.employee,

                employee_code:
                    info.employee_code,

                department:
                    info.department,

                shift:
                    info.shift,

                status:
                    'not_checked_in',

                check_in:
                    '',

                check_out:
                    '',

                working_minutes:
                    0,

                late_minutes:
                    0

            };


            if (
                attendance.next()
            ) {

                todaySummary
                    .not_checked_in--;


                if (
                    attendance.getValue(
                        'check_in'
                    )
                ) {

                    todaySummary
                        .checked_in++;

                }


                if (
                    attendance.getValue(
                        'check_out'
                    )
                ) {

                    todaySummary
                        .checked_out++;

                }


                var status =
                    attendance.getValue(
                        'status'
                    ) || '';


                row.status =
                    status;


                row.check_in =
                    convertToIndiaTime(
                        attendance.getValue(
                            'check_in'
                        )
                    );


                row.check_out =
                    convertToIndiaTime(
                        attendance.getValue(
                            'check_out'
                        )
                    );


                row.working_minutes =
                    parseInt(
                        attendance.getValue(
                            'working_minutes'
                        ) || 0,
                        10
                    );


                row.late_minutes =
                    parseInt(
                        attendance.getValue(
                            'late_minutes'
                        ) || 0,
                        10
                    );


                if (
                    status === 'late'
                ) {

                    todaySummary.late++;

                }

                else if (
                    status === 'present'
                ) {

                    todaySummary.present++;

                }

                else if (
                    status === 'half_day'
                ) {

                    todaySummary.half_day++;

                }

                else if (
                    status ===
                    'insufficient_hours'
                ) {

                    todaySummary
                        .insufficient_hours++;

                }

            }


            todayRows.push(
                row
            );

        }


        // =====================================================
        // LAST 7 DAYS SUMMARY
        // =====================================================
        var sevenDay = {

            from:
                startDate,

            to:
                today,

            attendance_records:
                0,

            present:
                0,

            late:
                0,

            half_day:
                0,

            insufficient_hours:
                0,

            total_late_minutes:
                0,

            total_working_minutes:
                0,

            average_working_minutes:
                0

        };


        if (
            employeeIds.length > 0
        ) {

            var history =
                new GlideRecord(
                    'x_1760545_smarta_0_attendance'
                );


            history.addQuery(
                'employee',
                'IN',
                employeeIds.join(',')
            );


            history.addQuery(
                'attendance_date',
                '>=',
                startDate
            );


            history.addQuery(
                'attendance_date',
                '<=',
                today
            );


            history.query();


            while (
                history.next()
            ) {

                sevenDay
                    .attendance_records++;


                var historyStatus =
                    history.getValue(
                        'status'
                    ) || '';


                if (
                    historyStatus ===
                    'present'
                ) {

                    sevenDay.present++;

                }

                else if (
                    historyStatus ===
                    'late'
                ) {

                    sevenDay.late++;

                }

                else if (
                    historyStatus ===
                    'half_day'
                ) {

                    sevenDay.half_day++;

                }

                else if (
                    historyStatus ===
                    'insufficient_hours'
                ) {

                    sevenDay
                        .insufficient_hours++;

                }


                sevenDay
                    .total_late_minutes +=
                    parseInt(
                        history.getValue(
                            'late_minutes'
                        ) || 0,
                        10
                    );


                sevenDay
                    .total_working_minutes +=
                    parseInt(
                        history.getValue(
                            'working_minutes'
                        ) || 0,
                        10
                    );

            }

        }


        if (
            sevenDay
                .attendance_records > 0
        ) {

            sevenDay
                .average_working_minutes =
                Math.round(

                    sevenDay
                        .total_working_minutes /

                    sevenDay
                        .attendance_records

                );

        }


        // =====================================================
        // RESPONSE
        // =====================================================
        response.setStatus(200);

        response.setBody({

            success:
                true,

            manager:
                gs.getUserDisplayName(),

            today:
                today,

            today_summary:
                todaySummary,

            seven_day_summary:
                sevenDay,

            employees:
                todayRows

        });


        // =====================================================
        // HELPER
        // =====================================================
        function convertToIndiaTime(
            value
        ) {

            if (!value) {
                return '';
            }


            var dt =
                new GlideDateTime(
                    value
                );


            dt.addSeconds(
                19800
            );


            return dt.getValue();

        }


    }
    catch (e) {

        gs.error(
            '[SmartAttend Dashboard] ' +
            e.message
        );


        response.setStatus(500);

        response.setBody({

            success:
                false,

            message:
                'Unable to load manager attendance dashboard.'

        });

    }

})(request, response);
